          ..write('id: $id, ')
          ..write('birthYear: $birthYear, ')
          ..write('bodyWeightKg: $bodyWeightKg, ')
          ..write('bodyHeightM: $bodyHeightM, ')
          ..write('restingHeartRateBpm: $restingHeartRateBpm, ')
          ..write('maxHeartRateBpm: $maxHeartRateBpm, ')
